entries[40767] = { ["name"] = "Überschallbooster", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+5 Ausdauer\nAnlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 Sek. lang Eure Angriffskraft um 14 . Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)\nBenötigt Ingenieurskunst von Nordend (15)\nVerkaufspreis:" }
