entries[40769] = { ["name"] = "Konstruktionsset: Schrottboter", ["text"] = "Benutzen: Erstellt einen mechanischen Schrottboter, der Ausrüstung repariert und fast alles kauft. Nach 5 Min. verschwindet er. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Nordend (50)\nVerkaufspreis:" }
entries[40771] = { ["name"] = "Kobaltsplitterbombe", ["text"] = "Benutzen: Fügt Zielen innerhalb von 3 Metern ( 29 * 10) bis ( 37 * 10) Feuerschaden zu und macht sie für 3 Sek. handlungsunfähig. Jeglicher Schaden bricht den Effekt ab.\n\nDie Splitterbombe hat keinen Effekt bei Kreaturen über Stufe 49. (1 Min Abklingzeit)\nBenötigt Ingenieurskunst von Nordend (1)\nVerkaufspreis:" }
entries[40772] = { ["name"] = "Gnomisches Armeemesser", ["text"] = "Benutzen: Ein Ingenieur mit einer Fähigkeit von mindestens 1 in der Ingenieurskunst von Nordend kann die Batterien des Messers überladen, um zu versuchen, einen toten Verbündeten ins Leben zurückzurufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\n+10 Fertigkeit in Bergbau von Nordend.\n+10 Fertigkeit in Kräuterkunde von Nordend.\n+10 Fertigkeit in Kürschnerei von Nordend.\n\"Beinhaltet einen gyromatischen Mikroregler, einen Bogenlichtschraubenschlüssel, eines Juwelierswerkzeugsatz, einen Schmiedehammer, einen Rückenkratzer und ein Kreiseldings.\"\nVerkaufspreis:" }
