entries[40775] = { ["name"] = "Geflügelter Greif der Schwarzen Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nKlassen: Todesritter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Euren geflügelten Greifen der Schwarzen Klinge oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ob tot oder lebendig. Dich nehm ich mit.\"\nVerkäufer:\nSchreckenskommandant Thalanor\nZone:\nÖstliche Pestländer\nKosten:" }
